<script setup lang="ts">
import { ref, watch } from "vue";
import { item, request, query, type TrialPolicy, type Plan, type Page } from "@papilio/api";
import { faNumber } from "@papilio/ui";
import NumField from "@papilio/ui/NumField.vue";
import {useI18n} from "vue-i18n";
const props=defineProps<{modelValue:TrialPolicy;disabled?:boolean}>();const emit=defineEmits<{"update:modelValue":[TrialPolicy]}>();
const {t}=useI18n();
const selected=ref<Plan|null>(null);const rows=ref<Plan[]>([]);const page=ref(1);const pages=ref(1);const q=ref("");const error=ref("");const state=ref<"idle"|"loading"|"ready"|"error">("idle");let version=0;
function change<K extends keyof TrialPolicy>(key:K,value:TrialPolicy[K]):void{emit("update:modelValue",{...props.modelValue,[key]:value});}
async function load():Promise<void>{const token=++version;state.value="loading";error.value="";try{const result=await request<Page<Plan>>(`/v1/admin/plans?${query({q:q.value,page:page.value,active:true})}`);if(token!==version)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;state.value="ready";}catch(cause){if(token!==version)return;state.value="error";error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}}
watch(()=>props.modelValue.plan_id,async id=>{selected.value=null;if(id===null)return;try{const result=await item<Plan>(`/v1/admin/plans/${id}`);if(props.modelValue.plan_id===id)selected.value=result;}catch(cause){error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}},{immediate:true});
const fields=[{key:"max_claims_per_customer",label:"claims"},{key:"cooldown_seconds",label:"cooldown"},{key:"quota_bytes",label:"quota"},{key:"duration_days",label:"duration"}] as const;
</script>
<template><fieldset :disabled="disabled" class="form-grid"><legend>{{t('settingsEditors.trial.title')}}</legend><label class="check-row"><input type="checkbox" :checked="modelValue.enabled" @change="change('enabled',($event.target as HTMLInputElement).checked)"/>{{t('settingsEditors.trial.enable')}}</label><label class="field"><span>{{t('settingsEditors.trial.eligibility')}}</span><select :aria-label="t('settingsEditors.trial.eligibility')" :value="modelValue.eligibility" @change="change('eligibility',($event.target as HTMLSelectElement).value as TrialPolicy['eligibility'])"><option value="no_paid_purchase">{{t('settingsEditors.trial.noPaid')}}</option><option value="any_customer">{{t('settingsEditors.trial.any')}}</option></select></label><label class="field"><span>{{t('settingsEditors.trial.concurrent')}}</span><select :aria-label="t('settingsEditors.trial.concurrent')" :value="modelValue.concurrent_mode" @change="change('concurrent_mode',($event.target as HTMLSelectElement).value as TrialPolicy['concurrent_mode'])"><option value="reject_active">{{t('settingsEditors.trial.reject')}}</option><option value="allow_multiple">{{t('settingsEditors.trial.multiple')}}</option></select></label><NumField v-for="field in fields" :key="field.key" :model-value="String(modelValue[field.key])" :label="t(`settingsEditors.trial.${field.label}`)" @update:model-value="change(field.key,Number($event))"/><p>{{t('settingsEditors.trial.hint')}}</p><p v-if="selected">{{t('settingsEditors.trial.source')}}: {{ selected.title }} · {{t(selected.is_active?'settingsEditors.trial.active':'settingsEditors.trial.inactive')}}</p><p v-else-if="modelValue.plan_id!==null">{{t('settingsEditors.trial.selected',{id:faNumber(modelValue.plan_id)})}}</p><p v-else>{{t('settingsEditors.trial.none')}}</p><p v-if="error" class="message error" role="alert">{{ error }}</p><div class="toolbar"><label class="field"><span>{{t('settingsEditors.trial.find')}}</span><input v-model="q" @keydown.enter.prevent="page=1;load()"/></label><button type="button" class="btn secondary" @click="page=1;load()">{{t('settingsEditors.trial.search')}}</button><button type="button" class="btn secondary" @click="change('plan_id',null)">{{t('settingsEditors.trial.clear')}}</button></div><p v-if="state==='loading'">{{t('settingsEditors.trial.loading')}}</p><p v-if="state==='ready'&&!rows.length">{{t('settingsEditors.trial.empty')}}</p><div class="inline-actions"><button v-for="row in rows" :key="row.id" type="button" class="btn secondary" :aria-pressed="modelValue.plan_id===row.id" @click="selected=row;change('plan_id',row.id)">{{ row.title }}</button></div><div v-if="state==='ready'" class="pager"><button type="button" :disabled="page<=1" @click="page--;load()">‹</button><span>{{t('settingsEditors.trial.of',{page:faNumber(page),pages:faNumber(pages)})}}</span><button type="button" :disabled="page>=pages" @click="page++;load()">›</button></div></fieldset></template>
